def is_samepatterns(colors, patterns):
    """
    Check whether the sequence `colors` follows the pattern given in `patterns`.

    A sequence follows the pattern if there is a consistent one-to-one
    (bijective) mapping between elements of `colors` and elements of `patterns`.

    Examples:
        is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) -> True
        is_samepatterns(["red", "green", "green"], ["a", "b", "c"]) -> False
        is_samepatterns(["red", "red", "red"],     ["a", "b", "c"]) -> False
    """
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        # Check forward mapping (color -> pattern)
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        # Check backward mapping (pattern -> color) to ensure bijection
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True


if __name__ == "__main__":
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) == True
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "c"]) == False
    assert is_samepatterns(["red", "red", "red"], ["a", "b", "c"]) == False
    assert is_samepatterns(["red", "green"], ["a", "b"]) == True
    assert is_samepatterns(["red"], ["a"]) == True
    print("All tests passed!")
